head, body = en.split("\n---\n", 1)
for lang, d in T.items():
    b = body
    # intro section
    b = re.sub(r'<h2>How to read this page</h2>\s*<p>.*?</p>', f'<h2>{d["how_t"]}</h2>\n{d["how"]}', b, count=1, flags=re.S)
    b = b.replace('placeholder="Filter references, e.g. “Estonia” or “2026”"', f'placeholder="{d["ph"]}"')
    for k, v in d["h"].items():
        b = b.replace(f"<h2>{k}</h2>", f"<h2>{v}</h2>")
    for k, v in d["toc"].items():
        b = b.replace(f'data-toc="{k}"', f'data-toc="{v}"')
    for k, v in d["flags"].items():
        b = b.replace(k, v)
    b = b.replace("<th>Figure on this site</th><th>Source</th>", f"<th>{d['th'][0]}</th><th>{d['th'][1]}</th>")
    b = b.replace("grouping by the author", d["grouping"])
    tbl_start = b.index('<section id="figures"')
    tbl = b[tbl_start:]
    rows = re.findall(r"<tr><td>(.*?)</td><td>", tbl)
    assert len(rows) == len(d["rows"]), (lang, len(rows), len(d["rows"]))
    for old, new in zip(rows, d["rows"]):
        tbl = tbl.replace(f"<tr><td>{old}</td>", f"<tr><td>{new}</td>", 1)
    b = b[:tbl_start] + tbl
    open(os.path.join(HERE, "content", f"sources.{lang}.html"), "w", encoding="utf-8").write(d["front"] + "---\n" + b)
    print("wrote", lang)
